procedure SelectionSort(a: array of real);
begin
  for var i:=0 to a.Length-2 do
  begin
    var (min,ind) := (a[i],i); 
    for var j:=i+1 to a.Length-1 do
      if a[j]<min then
        (min,ind) := (a[j],j); 
    a[ind] := a[i];
    a[i] := min;
  end;
end;

